INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (44, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'R4 backward mining of REF-00973''s reference list via api.crossref.org/works?query.bibliographic= — two titles it cites: ''An analysis of the effects of ramp slope on people with mobility impairments''; ''Kinematic and electromyographic analysis of wheelchair propulsion on ramps of different slopes for young men with paraplegia''', NULL, 'crossref', 'scoping', 'backward', 6, 6, 2, NULL, NULL, NULL, 0, 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-10 23:25', 'Both target papers resolved as the top hit of their query. Sanford/Story/Jones 1997 (Assistive Technology 9(1):22-33) is the ramp-slope paper the 2026 study cites as its design antecedent; Chow et al 2009 (Arch Phys Med Rehabil 90(2):271-278) measures propulsion on ramps of different slopes in young men with paraplegia. The other four hits were off-slug (postural control, disaster management, automatic wheelchair control) and are not staged. || CORRECTED 2026-09-10: CORRECTION: this row''s original note implied Sanford 1997 could not be graded. Two of three grounds were false. The PubMed DOI query was MALFORMED and never sent — curl exit 3, a 0-byte artefact in the manifest — and re-run encoded it returns PMID 10168021, whose abstract establishes a controlled design on 171 disabled participants across ramp slopes 1:8 to 1:20. Admitted as REF-00980, so this exec admitted 2, not 1. The only sound ground in the original note was that Crossref carries no abstract: true, and insufficient alone. R14: a query-shape failure was recorded as absence.', 0, 'REF-00973''s own reference list is in the persisted payload and cites two ramp-slope papers by title. Expect both to resolve and to state gradients directly. Cheapest lead source in the batch; satisfies R2''s mining floor with real chases rather than a deferral.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (45, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', NULL, '(ramp[Title/Abstract]) AND (wheelchair[Title/Abstract]) AND (qualitative[Title/Abstract] OR "lived experience"[Title/Abstract] OR participatory[Title/Abstract] OR "focus group"[Title/Abstract])', NULL, 'pubmed', 'systematic', NULL, 1, 1, 0, 'none', NULL, NULL, 0, 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-11 04:53', 'ONE hit, screened, NOT admitted, and the prior held. PMID 27664403 (Evaluating the Functionality and Usability of Two Novel Wheelchair Anti-Rollback Devices for Ramp Ascent in Manual Wheelchair Users With Spinal Cord Injury, PM R 2017, doi 10.1016/j.pmrj.2016.09.007) is a device-usability evaluation of two prototypes with 12 chronic-SCI participants on a fixed 7.3-m rig, rated with QUEST 2.0. It is NOT Co-1: the participants TESTED prototypes, they did not co-produce the research, and Co-1''s warrant is co-production (CLAUDE.md section 6). It is also off-parameter -- it reports no ramp gradient value, the ramp being a constant of the apparatus. THE FINDING IS ABOUT THE VENUE, NOT THE FIELD: the control query (ramp AND wheelchair, no methods clause) returned 97, so PubMed indexes this subject heavily and holds essentially no qualitative or participatory ramp-gradient work. Per R5 and R14 this is a well-formed query over the wrong index, not evidence of absence. A real Co-1 pass on ramp gradient has to run outside PubMed -- disability-studies and participatory-design venues, and DPO grey literature of the kind REF-00978 came from. || CORRECTED 2026-09-11: R7 flag raised. The single hit was not admitted, but it carries an INADEQUACY finding about assistive equipment on ramps: existing anti-rollback devices restrict backward motion, ''limiting recovery from an overturning wheelchair, which is a safety concern'', and are hard to engage or disengage while on the ramp (candidate 77, abstract Background). Flagged on the execution as well as the candidate because the gate''s R7 count reads search_executions only -- a harm finding recorded on a candidate alone is invisible to it, which is how a first-class finding becomes a hidden one.', 1, '0 to 3 hits, probably none admissible as Co-1. Every ramp-gradient source this slug has admitted is biomechanical -- kinematics, EMG, energy expenditure, rolling resistance -- on small clinical or able-bodied samples. Lived-experience and co-produced built-environment work publishes overwhelmingly in disability-studies and participatory-design venues PubMed does not index; R5 makes that an INDEXING fact, not an evidence-quality one, so a zero here is a finding about PubMed. FALSIFICATION: more than five relevant qualitative or co-produced ramp-gradient studies would mean my reading of where this literature lives is wrong. SHAPE RISK NAMED IN ADVANCE: PubMed AND-chains, so three simultaneous Title/Abstract constraints could produce a zero that is query-shape failure rather than absence (R14); if zero, re-run without the methods clause to separate the two.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (46, 'accessible-circulation-geometry', NULL, 'EN', 1, NULL, NULL, '(ramp[Title/Abstract]) AND (wheelchair[Title/Abstract])', NULL, 'pubmed', 'scoping', NULL, 97, 0, 0, 'none', NULL, NULL, 0, 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-11 04:53', '97. The control did its job: PubMed holds the ramp-wheelchair subject heavily, so exec 45''s single hit is a fact about where qualitative and co-produced work is PUBLISHED, not about query shape and not about whether the subject is indexed. NOT SCREENED, and that is deliberate rather than an omission -- this query was run to size the index, not to harvest, and the 40 ids returned under retmax were not read. Screening it is a separate unit of work; treating an unscreened control as a search that found nothing would be the R8 failure of a search log that cannot tell one from the other.', 0, 'This is the CONTROL for exec 45, run to separate query-shape failure from absence per R14, and its shape risk was named in exec 45''s prior BEFORE either query ran. Expectation: a substantial count -- tens at least -- because the biomechanical ramp-wheelchair literature this slug already draws on is PubMed-indexed. If this ALSO returned near-zero, exec 45''s zero would say nothing about Co-1 and would instead mean the index does not hold the subject at all.');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (76, 44, 'accessible-circulation-geometry', NULL, 'ADMITTED', 'Sanford JA, Story MF, Jones ML (1997) An Analysis of the Effects of Ramp Slope on People with Mobility Impairments. Assistive Technology 9(1):22-33. doi:10.1080/10400435.1997.10132293', NULL, NULL, 1, 0, 'HYPOTHESIS, not a finding (R15). Crossref metadata is complete and re-retrieved, but the study DESIGN is not established by any rung reached: PubMed returns count 0 on both DOI and exact-title search, and Crossref carries no abstract. scope therefore cannot be derived from bytes, and an undeclared scope makes the tier underivable and the source NON-ANCHORING under B5a anyway. Admitting it on the inference that ''An Analysis of the Effects of X'' implies a controlled design is exactly what left four rows NULL in B5b. Resolve by obtaining the article and re-describing from the source.', 'R5: absence from PubMed is an INDEXING fact about a 1997 Assistive Technology paper, not an evidence-quality fact. R2: this is REF-00973''s own cited antecedent, so the lead is well-founded even while the grade is not. || RESOLVED 2026-09-10 (R15, re-described from the source; admitted as REF-00980): A controlled usability evaluation of the ramp-slope range the ADA guidelines permit: 171 subjects of all ages using different types of mobility aids traversed a 30-foot ramp varying in slope from 1:8 to 1:20. It measures the parameter directly across that range, and its finding runs CONTRARY to REF-00973''s — only a few manual wheelchair users had difficulty traversing all 30 feet in ascent even at 1:8, and the authors conclude changes to the technical requirements cannot be recommended. My staging note claimed the design was unreachable because PubMed returned count 0 on the DOI search. That query was never sent: curl exited 3 on an unencoded [DOI] term and the manifest logged a 0-byte artefact with exit=3. Properly encoded, it returns PMID 10168021. I recorded a query-shape failure as absence, which is the exact conflation R14 exists to stop.', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-10 23:26');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (77, 45, 'accessible-circulation-geometry', NULL, 'OUT-OF-SCOPE', 'Evaluating the Functionality and Usability of Two Novel Wheelchair Anti-Rollback Devices for Ramp Ascent in Manual Wheelchair Users With Spinal Cord Injury', '10.1016/j.pmrj.2016.09.007', 'RESOLVED', 1, 1, 'Off-parameter and not Co-1. It reports no ramp gradient value -- the 7.3-m ramp is a constant of the test rig, not a variable -- so it cannot speak to TERM-001. And it is not Co-1 despite surfacing on a co1-targeted query: twelve chronic-SCI participants TESTED two prototypes and rated them on QUEST 2.0; Co-1''s warrant is co-production, not participation as a test subject (CLAUDE.md section 6). Admitting it on the strength of the word ''qualitative'' in its conclusion would be the tier-by-keyword failure the Co-1 definition exists to prevent.', 'R7 HARM FINDING, which is why this is recorded rather than dropped. Its own premise is a safety defect in the devices already on the market: existing anti-rollback devices ''have 2 main shortcomings: restriction to backward motion limiting recovery from an overturning wheelchair, which is a safety concern; and difficulty in engaging/disengaging the device while on the ramp'' (abstract, Background). That is an INADEQUACY finding about assistive equipment on ramps, first-class evidence under R7 even though the paper is off-parameter for gradient. It also independently corroborates that ramp ascent is hard enough to have spawned a device class: ''Difficulty ascending ramps and inclines with a manual wheelchair adversely affects the everyday mobility and overall quality of life of manual wheelchair users.'' REHOME CANDIDATE for any future slug on assistive-equipment adequacy; kept OUT-OF-SCOPE here rather than REHOME because no such slug exists to name.', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-11 04:53');
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-10-resea-REF-00979-MOB', 'REF-00979', 'MOB', 'Young men (N=10) with paraplegia; repeated-measures, wooden ramp 7.3 m, slopes 0-12 degrees, biomechanics laboratory (PMID 19236980 abstract)', 10, 'PARTIAL', 'Male-only, young-only, paraplegia-only, N=10. No powerchair or scooter users, no women, no older adults. MOB spans mobility-aid users this sample does not represent, and the 4-10 degree adjustment band it reports is a manual-wheelchair upslope finding.', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry', 'REF-00979', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-10-resea-REF-00979-SCI', 'REF-00979', 'SCI', 'Young men (N=10) with paraplegia; aetiology NOT reported (PMID 19236980 abstract)', 10, 'PARTIAL', 'The source states PARAPLEGIA, not spinal cord injury, and PubMed indexes it under the Paraplegia descriptor with no Spinal Cord Injuries term. Paraplegia also follows spina bifida, transverse myelitis and tumour, so an SCI reading is inferred from presentation rather than stated. Compare REF-00973, graded EXACT on SCI because it reports C4-T12 AIS A/B/C explicitly.', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry', 'REF-00979', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-10-resea-REF-00980-MOB', 'REF-00980', 'MOB', '171 subjects of all ages using different types of mobility aids, traversing a 30-foot ramp at slopes from 1:8 to 1:20 (PMID 10168021 abstract)', 171, 'EXACT', 'Graded from the abstract; the full text was not read. The abstract states all ages and different types of mobility aids but does not enumerate the device types or their proportions, so the breadth is asserted by the source rather than shown. Its own finding is stratified -- only a few MANUAL wheelchair users had difficulty at 1:8 -- so device type is load-bearing for any value drawn from it.', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry', 'REF-00980', NULL);
