INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (1, 34, 'NAMES-EXISTING', 'TERM-001', 'the source''s own phrase for the parameter TERM-001 already names; no new concept', '2026-09-10 23:16', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-10 23:16', 'session_2026-09-10-research-batch-06-circulation-geometry');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (2, 35, 'NAMES-EXISTING', 'TERM-001', 'the source''s own phrase for the parameter TERM-001 already names; no new concept', '2026-09-10 23:16', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-10 23:16', 'session_2026-09-10-research-batch-06-circulation-geometry');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (3, 36, 'NAMES-EXISTING', 'TERM-001', 'The source''s own phrase for the parameter TERM-001 ''ramp gradient'' already names. ''Slope'' and ''gradient'' are the same quantity under two names; no new concept, and coining one would create the rule-5 dual home TERM-003 ''turning circle'' was nearly given.', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (4, 37, 'NAMES-EXISTING', 'TERM-001', '''Upslope'' qualifies the DIRECTION of travel on the same parameter, not a second parameter. Recorded because the source''s finding is direction-specific -- ascent -- and a determination drawn from it inherits that, which the verbatim phrase preserves and a normalised one would lose.', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (5, 38, 'NAMES-EXISTING', 'TERM-001', '''Ramp slope'' is TERM-001 ''ramp gradient'' in the source''s words. Same adjudication as observations 34/35 on REF-00973/974, kept consistent so the term store does not fragment by verbatim label.', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (6, 39, 'NAMES-EXISTING', 'TERM-001', 'Names TERM-001 while attaching it to a regulatory range (ADA 1:8 to 1:20). The phrase is kept verbatim because the ADA anchoring is what makes this source''s values jurisdiction-bound, a T4-6 property the extraction must carry rather than the term store.', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-11 04:50', 'session_2026-09-10-research-batch-06-circulation-geometry');
