INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (2, 'REF-00974', 'accessible-circulation-geometry', 1, 'MOB', NULL, NULL, NULL, NULL, NULL, 'absent', NULL, NULL, 'wheelchair propulsion at different speeds and inclines, ascending and descending ramps, weight relief lift, material handling and desk work', 'Abstract', NULL, 'measurement_primary', 'REF-00974', NULL, 'instrumented_physical_measurement', 'manual_self_propelled', 'ten able-bodied participants — PROXY for the served population', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'absent-confirmed', NULL, 'Addresses the parameter as an experimental condition and states NO gradient value anywhere in the retrieved abstract. Graded absent rather than manufacturing a figure. Shoulder-load outcomes are real but are not values FOR this parameter.', '2026-09-10 23:19', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-10 23:19', 'session_2026-09-10-research-batch-06-circulation-geometry');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (3, 'REF-00980', 'accessible-circulation-geometry', 1, 'MOB', NULL, NULL, NULL, NULL, NULL, 'range', '1:8 to 1:20', 'ratio (rise:run)', 'One hundred seventy-one subjects of all ages and using different types of mobility aids traversed a 30-foot ramp varying in slope from 1:8 to 1:20.', 'Abstract', NULL, 'measurement_primary', 'REF-00980', NULL, 'instrumented_physical_measurement', 'mixed', '171 subjects of all ages using different types of mobility aids', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'CONTRARY to REF-00973 on the same parameter: this study reports only a few manual wheelchair users had difficulty traversing all 30 feet in ascent even at 1:8, and concludes changes to the technical requirements cannot be recommended, where REF-00973 finds MD risk rising with gradient in two steps. A real divergence for synthesis to weigh, not a discrepancy to reconcile away.', '2026-09-10 23:33', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-10 23:33', 'session_2026-09-10-research-batch-06-circulation-geometry');